                                    let rarityState = {
                                      luck: 0,
                                      dropsSinceRare: 0,
                                      dropsSinceEpic: 0,
                                      dropsSinceLegendary: 0,
                                      dropsSinceMythic: 0,
                                      dropsSinceDivine: 0
                                    };

                                    function getRarityRank(rarity) { return Math.max(0, RARITY_ORDER.indexOf(rarity || 'common')); }
                                                                  function clampRarity(rarity) { return RARITIES[rarity] ? rarity : 'common'; }
                                    function randomBetween(a, b) { return a + Math.random() * (b - a); }

                                    function getRarityLuck() {
                                      const waveLuck = Math.min(2.5, Math.max(0, (wave - 1) * 0.025));
                                      return Math.max(0, Number(rarityState.luck) || 0) + waveLuck;
                                    }

                                    function getRarityWeights() {
                                      const luck = getRarityLuck();
                                      const weights = {};
                                      for (const rarity of RARITY_ORDER) {
                                        const data = RARITIES[rarity];
                                        if (wave < data.minWave) { weights[rarity] = 0; continue; }
                                        const rank = getRarityRank(rarity);
                                        weights[rarity] = data.dropWeight * (1 + luck * rank * RARITY_SYSTEM.luckPerPoint);
                                      }
                                      // Soft pity: steadily increases the weight of the next tiers instead of
                                      // making high-tier drops appear randomly with no protection against bad streaks.
                                      const pity = Math.max(0, rarityState.dropsSinceRare - RARITY_SYSTEM.pityStart);
                                      if (weights.rare) weights.rare *= 1 + pity * RARITY_SYSTEM.pityStep;
                                      if (rarityState.dropsSinceEpic >= RARITY_SYSTEM.guaranteed.epic - 1 && wave >= RARITIES.epic.minWave) weights.epic *= 5;
                                      if (rarityState.dropsSinceLegendary >= RARITY_SYSTEM.guaranteed.legendary - 1 && wave >= RARITIES.legendary.minWave) weights.legendary *= 7;
                                      if (rarityState.dropsSinceMythic >= RARITY_SYSTEM.guaranteed.mythic - 1 && wave >= RARITIES.mythic.minWave) weights.mythic *= 10;
                                      if (rarityState.dropsSinceDivine >= RARITY_SYSTEM.guaranteed.divine - 1 && wave >= RARITIES.divine.minWave) weights.divine *= 14;
                                      return weights;
                                    }

                                    function updateRarityPity(rolled) {
                                      for (const key of ['dropsSinceRare','dropsSinceEpic','dropsSinceLegendary','dropsSinceMythic','dropsSinceDivine']) rarityState[key]++;
                                      const rank = getRarityRank(rolled);
                                      if (rank >= 2) rarityState.dropsSinceRare = 0;
                                      if (rank >= 3) rarityState.dropsSinceEpic = 0;
                                      if (rank >= 4) rarityState.dropsSinceLegendary = 0;
                                      if (rank >= 5) rarityState.dropsSinceMythic = 0;
                                      if (rank >= 6) rarityState.dropsSinceDivine = 0;
                                    }

                                    function rollRarityAffixes(rarity) {
                                      const data = RARITIES[rarity] || RARITIES.common;
                                      const pool = Object.values(RARITY_AFFIXES);
                                      const count = Math.min(data.affixSlots || 0, pool.length);
                                      const shuffled = pool.slice().sort(() => Math.random() - 0.5);
                                      return shuffled.slice(0, count).map(affix => ({ ...affix, value: randomBetween(affix.min, affix.max) }));
                                    }

                                    function rollWeaponQuality(rarity) {
                                      const data = RARITIES[rarity] || RARITIES.common;
                                      const variance = RARITY_SYSTEM.qualityVariance ? randomBetween(-data.statRoll, data.statRoll) : 0;
                                      return Math.max(0.01, 1 + variance);
                                    }

