      function isSprintHeld() {
        return isSprintKeyDown();
      }

      function consumeStamina(amount) {
        if (!Number.isFinite(amount) || amount <= 0) {
          return true;
        }

        if (hasRoundModifier('infiniteStamina')) {
          stamina = MAX_STAMINA;
          staminaRegenDelay = 0;
          sprintExhausted = false;
          staminaWarningCooldown = 0;

          return true;
        }

        if (stamina < amount) {
          return false;
        }

        stamina = Math.max(0, stamina - amount);
        staminaRegenDelay = STAMINA_REGEN_DELAY;

        if (stamina <= 0) {
          sprintExhausted = true;
        }

        return true;
      }

      function updateStamina(dt, moving = false, sprinting = false) {
        const safeDt = THREE.MathUtils.clamp(
          Number(dt) || 0,
          0,
          0.05
        );

        staminaWarningCooldown = Math.max(
          0,
          staminaWarningCooldown - safeDt
        );

        if (safeDt <= 0) {
          renderStaminaHud();
          return;
        }

        if (hasRoundModifier('infiniteStamina')) {
          stamina = MAX_STAMINA;
          staminaRegenDelay = 0;
          sprintExhausted = false;
          staminaWarningCooldown = 0;

          renderStaminaHud();
          return;
        }

        stamina = THREE.MathUtils.clamp(
          Number.isFinite(stamina) ? stamina : MAX_STAMINA,
          0,
          MAX_STAMINA
        );

        staminaRegenDelay = Math.max(
          0,
          staminaRegenDelay - safeDt
        );

        if (sprinting && moving && !sprintExhausted) {
          stamina = Math.max(
            0,
            stamina - STAMINA_DRAIN * safeDt
          );

          staminaRegenDelay = STAMINA_REGEN_DELAY;

          if (stamina <= 0) {
            stamina = 0;
            sprintExhausted = true;
          }

          renderStaminaHud();
          return;
        }

        if (!isSprintHeld()) {
          sprintExhausted = false;
        }

        const sprintingWhileMoving =
          isSprintHeld() &&
          moving &&
          !sprintExhausted;

        // Do not regenerate while sliding or during the regen delay.
        if (
          sliding ||
          staminaRegenDelay > 0 ||
          sprintingWhileMoving
        ) {
          renderStaminaHud();
          return;
        }

        stamina = Math.min(
          MAX_STAMINA,
          stamina + STAMINA_REGEN * safeDt
        );

        if (stamina >= STAMINA_EXHAUSTED_THRESHOLD) {
          sprintExhausted = false;
        }

        renderStaminaHud();
      }

      function getSafeStamina() {
        const value = Number.isFinite(stamina)
          ? stamina
          : MAX_STAMINA;

        return THREE.MathUtils.clamp(
          value,
          0,
          MAX_STAMINA
        );
      }

      function renderStaminaHud() {
        const fill = document.getElementById('staminaFill');
        const bar = document.querySelector('#staminaHud .stamina-bar');

        if (!fill) {
          return;
        }

        const value = getSafeStamina();
        const ratio = value / MAX_STAMINA;
        const percent = Math.round(ratio * 100);

        fill.style.width = `${percent}%`;
        fill.setAttribute('aria-valuenow', String(percent));

        if (bar) {
          bar.setAttribute('aria-valuenow', String(percent));
          bar.setAttribute(
            'aria-valuetext',
            `${percent}% stamina`
          );
        }

        const staminaHud = document.getElementById('staminaHud');

        if (staminaHud) {
          staminaHud.dataset.staminaState =
            percent <= 0
              ? 'empty'
              : percent <= STAMINA_EXHAUSTED_THRESHOLD
                ? 'low'
                : 'normal';
        }
      }

      function updateStaminaHudImmediate() {
        renderStaminaHud();
      }

      const CORE_TUNING = createCoreTuning();


