      function setSaveStatus(message, isError = false) {
        const statusElements = [
          document.getElementById('saveStatus'),
          document.getElementById('deathSaveStatus')
        ].filter(Boolean);

        for (const status of statusElements) {
          status.textContent = message;
          status.style.color = isError ? '#fca5a5' : '#86efac';
        }
      }

      function createSaveData() {
        const weaponRarityData = {};
        const weaponRollData = {};

        for (const [key, weapon] of Object.entries(W)) {
          if (weapon && weapon.rarity) {
            weaponRarityData[key] = weapon.rarity;
            weaponRollData[key] = {
              quality: Number.isFinite(weapon.quality) ? weapon.quality : 1,
              affixes: Array.isArray(weapon.affixes) ? weapon.affixes.map(a => ({ label:a.label, stat:a.stat, value:a.value })) : []
            };
          }
        }

        return {
          format: 'killshift-save',
          version: 2,
          savedAt: new Date().toISOString(),

          loadout: [...loadout],
          unlockedWeapons: [...unlockedWeapons],
          weaponRarities: weaponRarityData,
          weaponRolls: weaponRollData,
          rarityState: { ...rarityState },

          ownedAbilities: [...ownedAbilities],
          activeAbilities: [...activeAbilities],

          coins,
          score,
          wave,
          highestWaveReached,

          elevatorTargetWave,
          elevatorUsed,

          ammo: Object.fromEntries(
            Object.entries(ammo).map(([key, state]) => [
              key,
              {
                mag: Number.isFinite(state.mag) ? state.mag : 0,
                reserve: Number.isFinite(state.reserve)
                  ? state.reserve
                  : 'Infinity'
              }
            ])
          )
        };
      }
      function getWeaponAbilityStacks(id) {
        if (typeof abilityOwnedCount === 'function') {
          return abilityOwnedCount(id);
        }

        return 0;
      }

      function hasWeaponAbility(id) {
        return getWeaponAbilityStacks(id) > 0;
      }

      function getWeaponAbilityDamageMultiplier(enemy, baseDamage) {
        let damage = baseDamage;

        if (
          enemy &&
          enemy.maxHp > 0 &&
          enemy.hp / enemy.maxHp <= 0.25 &&
          hasWeaponAbility('executionProtocol')
        ) {
          const stacks = getWeaponAbilityStacks('executionProtocol');
          damage *= 1 + 0.35 * stacks;
        }

        if (
          enemy &&
          weaponAbilityState.lastTarget === enemy &&
          hasWeaponAbility('armorBreaker')
        ) {
          const stacks = getWeaponAbilityStacks('armorBreaker');
          damage *= 1 + Math.min(1.2, weaponAbilityState.consecutiveHits * 0.08 * stacks);
        }

        if (hasWeaponAbility('momentumBarrel')) {
          const stacks = getWeaponAbilityStacks('momentumBarrel');

          if (weaponAbilityState.momentumTimer > 0) {
            damage *= 1 + Math.min(0.45, stacks * 0.06);
          }
        }

        return damage;
      }

      function registerWeaponHit(enemy) {
        if (!enemy) {
          return;
        }

        if (weaponAbilityState.lastTarget === enemy) {
          weaponAbilityState.consecutiveHits++;
        } else {
          weaponAbilityState.lastTarget = enemy;
          weaponAbilityState.consecutiveHits = 1;
        }

        if (hasWeaponAbility('momentumBarrel')) {
          weaponAbilityState.momentumTimer = 2.5;
        }
      }

      function updateWeaponAbilityState(dt) {
        weaponAbilityState.momentumTimer = Math.max(
          0,
          weaponAbilityState.momentumTimer - dt
        );

        weaponAbilityState.elementalCooldown = Math.max(
          0,
          weaponAbilityState.elementalCooldown - dt
        );
      }
      function validateSaveData(data) {
        if (!data || typeof data !== 'object') {
          throw new Error('Save data is not an object.');
        }

        if (data.format !== 'killshift-save') {
          throw new Error('This is not a Killshift save file.');
        }

        if (data.version !== 1 && data.version !== 2) {
          throw new Error('Unsupported save file version.');
        }

        if (!Array.isArray(data.loadout)) {
          throw new Error('Save file has an invalid loadout.');
        }

        if (!Array.isArray(data.unlockedWeapons)) {
          throw new Error('Save file has invalid weapon data.');
        }

        if (!Array.isArray(data.ownedAbilities)) {
          throw new Error('Save file has invalid ability data.');
        }

        return true;
      }

      function applySaveData(data) {
        validateSaveData(data);

        const validLoadout = data.loadout
          .filter(key => typeof key === 'string' && W[key])
          .slice(0, 5);

        while (validLoadout.length < 5) {
          validLoadout.push(null);
        }

        loadout = validLoadout;

        unlockedWeapons = new Set(
          data.unlockedWeapons.filter(key => W[key])
        );

        for (const key of loadout) {
          if (key && W[key]) {
            unlockedWeapons.add(key);
          }
        }

        for (const [key, rarity] of Object.entries(data.weaponRarities || {})) {
          if (W[key] && RARITIES[rarity]) {
            W[key].rarity = rarity;
            const savedRoll = data.weaponRolls?.[key];
            if (savedRoll) {
              W[key].quality = Number.isFinite(savedRoll.quality) ? savedRoll.quality : 1;
              W[key].affixes = Array.isArray(savedRoll.affixes) ? savedRoll.affixes : [];
            }
            applyWeaponRarity(W[key]);
            applyRarityEffect(W[key], rarity);
          }
        }

        if (data.rarityState && typeof data.rarityState === 'object') {
          rarityState = { ...rarityState, ...data.rarityState };
        }

        ownedAbilities = data.ownedAbilities.filter(
          id => ABILITY_CATALOG[id]
        );

      const savedActiveAbilities = Array.isArray(data.activeAbilities)
        ? data.activeAbilities
        : [];

      activeAbilities = savedActiveAbilities
        .filter(id => ABILITY_CATALOG[id])
        .slice(0, 3);

        coins = Math.max(0, Number(data.coins) || 0);
        loadedResumeScore = Math.max(0, Number(data.score) || 0);
        loadedResumeWave = Math.max(1, Math.floor(Number(data.wave) || 1));

        highestWaveReached = Math.max(
          1,
          Math.floor(Number(data.highestWaveReached) || loadedResumeWave)
        );

        elevatorTargetWave = Math.max(
          1,
          Math.floor(Number(data.elevatorTargetWave) || 1)
        );

        elevatorUsed = Boolean(data.elevatorUsed);

        resetAmmo();

        for (const [key, savedAmmo] of Object.entries(data.ammo || {})) {
          if (!ammo[key] || !savedAmmo) {
            continue;
          }

          ammo[key].mag = Math.max(
            0,
            Math.floor(Number(savedAmmo.mag) || 0)
          );

          ammo[key].reserve =
            savedAmmo.reserve === 'Infinity'
              ? Infinity
              : Math.max(
                  0,
                  Math.floor(Number(savedAmmo.reserve) || 0)
                );
        }

        selected = Math.min(
          selected,
          Math.max(0, loadout.length - 1)
        );

        renderSlots();
        updateGameHud();
        updateHealthHud();

        showLoadout('start');
      }

      function saveGame() {
        try {
          const saveData = createSaveData();

          localStorage.setItem(
            SAVE_STORAGE_KEY,
            JSON.stringify(saveData)
          );

          setSaveStatus('Game saved successfully.');
          return true;
        } catch (error) {
          console.error('Unable to save game:', error);
          setSaveStatus('Unable to save the game.', true);
          return false;
        }
      }

      function loadGame() {
        try {
          const rawSave = localStorage.getItem(SAVE_STORAGE_KEY);

          if (!rawSave) {
            setSaveStatus('No saved game was found.', true);
            return false;
          }

          const saveData = JSON.parse(rawSave);
          applySaveData(saveData);

          setSaveStatus(
            `Game loaded. Resume from Wave ${loadedResumeWave}.`
          );

          return true;
        } catch (error) {
          console.error('Unable to load game:', error);
          setSaveStatus('The saved game is invalid or corrupted.', true);
          return false;
        }
      }

      function exportGame() {
        try {
          const saveData = createSaveData();
          const json = JSON.stringify(saveData, null, 2);
          const blob = new Blob([json], {
            type: 'application/json'
          });

          const url = URL.createObjectURL(blob);
          const link = document.createElement('a');

          link.href = url;
          link.download = `killshift-save-${Date.now()}.json`;
          document.body.appendChild(link);
          link.click();
          link.remove();

          URL.revokeObjectURL(url);

          setSaveStatus('Save file exported.');
        } catch (error) {
          console.error('Unable to export game:', error);
          setSaveStatus('Unable to export the save file.', true);
        }
      }

      function importGame(file) {
        if (!file) {
          return;
        }

        const reader = new FileReader();

        reader.onload = () => {
          try {
            const saveData = JSON.parse(reader.result);
            applySaveData(saveData);

            localStorage.setItem(
              SAVE_STORAGE_KEY,
              JSON.stringify(saveData)
            );

            setSaveStatus('Save file imported successfully.');
          } catch (error) {
            console.error('Unable to import save:', error);
            setSaveStatus(
              'The imported file is invalid.',
              true
            );
          }
        };

        reader.onerror = () => {
          setSaveStatus('Unable to read the selected file.', true);
        };

        reader.readAsText(file);
      }

      function deleteSave() {
        const confirmed = window.confirm(
          'Delete the saved game permanently?'
        );

        if (!confirmed) {
          return;
        }

        localStorage.removeItem(SAVE_STORAGE_KEY);
        setSaveStatus('Saved game deleted.');
      }

      function bindSaveControls() {
        const bind = (id, eventName, handler) => {
          const element = document.getElementById(id);

          if (element) {
            element.addEventListener(eventName, handler);
          }
        };

        bind('saveGameBtn', 'click', saveGame);
        bind('loadGameBtn', 'click', loadGame);
        bind('exportGameBtn', 'click', exportGame);
        bind('deleteSaveBtn', 'click', deleteSave);

        bind('importGameInput', 'change', event => {
          importGame(event.target.files?.[0]);
          event.target.value = '';
        });

        bind('deathSaveGameBtn', 'click', saveGame);
        bind('deathLoadGameBtn', 'click', loadGame);
        bind('deathExportGameBtn', 'click', exportGame);
        bind('deathDeleteSaveBtn', 'click', deleteSave);

        bind('deathImportGameInput', 'change', event => {
          importGame(event.target.files?.[0]);
          event.target.value = '';
        });
      }

      bindSaveControls();

