                                        weapon.baseCritChance ??= Number.isFinite(weapon.critChance) ? weapon.critChance : (weapon.crit ? 0.15 : 0);
                                        weapon.baseCritDamage ??= Number.isFinite(weapon.critDamage) ? weapon.critDamage : 2;
                                        weapon.baseStatusPower ??= Number.isFinite(weapon.statusPower) ? weapon.statusPower : 1;
                                        weapon.baseAbilityPower ??= Number.isFinite(weapon.abilityPower) ? weapon.abilityPower : 1;
