                                    function applyWeaponRarity(weapon) {
                                      if (!weapon) return;
                                      const rarityName = clampRarity(weapon.rarity);
                                      const rarity = RARITIES[rarityName];
                                      weapon.rarity = rarityName;
                                      const quality = Number.isFinite(weapon.quality) ? weapon.quality : 1;
                                      const q = rarityName === 'common' ? 1 : quality;
                                      weapon.damage = Math.max(0, Math.floor(weapon.baseDamage * rarity.damage * q));
                                      weapon.rate = Math.max(1, weapon.baseRate / rarity.fireRate);
                                      weapon.mag = Math.max(1, Math.floor(weapon.baseMag * rarity.ammo * q));
                                      weapon.reserve = Number.isFinite(weapon.baseReserve) ? Math.max(0, Math.floor(weapon.baseReserve * rarity.ammo * q)) : weapon.baseReserve;
                                      weapon.reload = Number.isFinite(weapon.baseReload) ? Math.max(40, weapon.baseReload * rarity.reload) : weapon.baseReload;
                                      weapon.range = Number.isFinite(weapon.baseRange) ? Math.max(0, weapon.baseRange * rarity.range) : weapon.baseRange;
                                      weapon.spread = Number.isFinite(weapon.baseSpread) ? Math.max(0, weapon.baseSpread * rarity.spread) : weapon.baseSpread;
                                      weapon.critChance = Math.min(0.95, weapon.baseCritChance + rarity.critChance);
                                      weapon.critDamage = weapon.baseCritDamage * rarity.critDamage;
                                      weapon.projectileSpeed = weapon.baseProjectileSpeed * rarity.projectileSpeed;
                                      weapon.statusPower = weapon.baseStatusPower * rarity.statusPower;
                                      weapon.abilityPower = weapon.baseAbilityPower * rarity.abilityPower;
                                      weapon.knockback = weapon.baseKnockback * rarity.damage;
                                      if (weapon.affixes?.length) {
                                        for (const affix of weapon.affixes) {
                                          if (!affix || !Number.isFinite(affix.value)) continue;
                                          if (affix.stat === 'damage') weapon.damage *= affix.value;
                                          if (affix.stat === 'fireRate') weapon.rate /= affix.value;
                                          if (affix.stat === 'reload') weapon.reload *= affix.value;
                                          if (affix.stat === 'mag') weapon.mag = Math.floor(weapon.mag * affix.value);
                                          if (affix.stat === 'range') weapon.range *= affix.value;
                                          if (affix.stat === 'critChance') weapon.critChance = Math.min(.95, weapon.critChance + affix.value);
                                          if (affix.stat === 'projectileSpeed') weapon.projectileSpeed *= affix.value;
                                          if (affix.stat === 'statusPower') weapon.statusPower *= affix.value;
                                          if (affix.stat === 'abilityPower') weapon.abilityPower *= affix.value;
                                        }
                                      }
                                      weapon.damage = Math.max(0, Math.floor(weapon.damage));
                                      weapon.mag = Math.max(1, Math.floor(weapon.mag));
                                    }

