        ctx.lineTo(size * 0.65, size * 0.75);
        ctx.lineTo(0, size * 0.4);
        ctx.lineTo(-size * 0.65, size * 0.75);
        ctx.closePath();

        ctx.fillStyle = fill;
        ctx.fill();

