        const scale = radius / distance;
        const x = centerX + directionX * scale;
        const y = centerY + directionY * scale;

        ctx.save();

        ctx.fillStyle = color;
        ctx.globalAlpha = 0.9;
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();

