        const height = miniMapHeight;

        const centerX = width * 0.5;
        const centerY = height * 0.5;
        const radarRadius = Math.min(width, height) * 0.485;

        const radarRange = Math.min(
          worldBounds,
          Math.max(28, 34 + Math.hypot(moveVelocityX, moveVelocityZ) * 0.25)
        );

        const playerX = camera.position.x;
        const playerZ = camera.position.z;

        const direction = new THREE.Vector3();
        camera.getWorldDirection(direction);

        const heading = Math.atan2(direction.x, direction.z);

      miniMapScanTime += Math.max(0, Math.min(dt, 0.1));

        if (miniMapRangeElement) {
          miniMapRangeElement.textContent = `RANGE ${Math.round(radarRange)}M`;
        }

