                          function addObstacleMesh(mesh, options = {}) {
              if (!mesh) {
                return null;
              }

              mesh.updateMatrixWorld(true);

              const hitbox = new THREE.Box3().setFromObject(mesh);

              const obstacle = {
                mesh,
                hitbox,

                minX: hitbox.min.x,
                maxX: hitbox.max.x,
                minY: hitbox.min.y,
                maxY: hitbox.max.y,
                minZ: hitbox.min.z,
                maxZ: hitbox.max.z,

                width: hitbox.max.x - hitbox.min.x,
                height: hitbox.max.y - hitbox.min.y,
                depth: hitbox.max.z - hitbox.min.z,

                blocksMovement: options.blocksMovement !== false,
                blocksShots: options.blocksShots !== false,

                climbable: options.climbable !== false
              };

              obstacles.push(obstacle);

              return mesh;
            }

            function addObstacleBox(
              x,
              y,
              z,
              width,
              height,
              depth,
              material = wallMat,
              options = {}
            ) {
              const mesh = new THREE.Mesh(
                new THREE.BoxGeometry(width, height, depth),
                material
              );

              mesh.position.set(
                x,
                y + height / 2,
                z
              );

              mesh.castShadow = true;
              mesh.receiveShadow = true;

              scene.add(mesh);
              addObstacleMesh(mesh, options);

              return mesh;
            }

            function addBuilding(
              x,
              z,
              width,
              depth,
              height,
              material = wallMat
            ) {
              return addObstacleBox(
                x,
                0,
                z,
                width,
                height,
                depth,
                material
              );
            }

                        function addObstacleCylinder(mesh, radius) {
                          if (!mesh) {
                            return null;
                          }

                          mesh.updateMatrixWorld(true);

                          const center = mesh.getWorldPosition(new THREE.Vector3());

                          const hitbox = new THREE.Box3(
                            new THREE.Vector3(
                              center.x - radius,
                              center.y - radius,
                              center.z - radius
                            ),
                            new THREE.Vector3(
                              center.x + radius,
                              center.y + radius,
                              center.z + radius
                            )
                          );

                          obstacles.push({
                            mesh,
                            hitbox,

                            minX: hitbox.min.x,
                            maxX: hitbox.max.x,
                            minZ: hitbox.min.z,
                            maxZ: hitbox.max.z,
                            minY: hitbox.min.y,
                            maxY: hitbox.max.y,

                            width: radius * 2,
                            depth: radius * 2
                          });

                          return mesh;
                        }

