                        function processShotModifiers(weapon) {
                          playerShotCounter++;

                          const hasPhaseShift =
                            hasActiveAbility('phaseShift') &&
                            playerShotCounter % 7 === 0;

                          const hasEchoShot =
                            hasActiveAbility('echoChamber') &&
                            playerShotCounter % 5 === 0;

                          if (hasEchoShot) {
                            setTimeout(() => {
                              if (alive && !dying) {
                                fireEchoShot(weapon);
                              }
                            }, 80);
                          }

                          return {
                            ignoreWalls: hasPhaseShift
                          };
                        }

                                    function updateAirdrops(dt) {
                                      for (const drop of airdrops) {
                                        if (!drop || drop.collected) {
                                          continue;
                                        }

                                        if (drop.falling) {
                                          drop.group.position.y -= 7 * dt;

                                          if (drop.group.position.y <= drop.targetY) {
                                            drop.group.position.y = drop.targetY;
                                            drop.falling = false;

                                            showFeed(
                                              drop.type === 'health'
                                                ? 'HEALTH AIRDROP LANDED'
                                                : drop.type === 'ammo'
                                                  ? 'AMMO AIRDROP LANDED'
                                                  : 'BLUE WEAPON AIRDROP LANDED',
                                              drop.type === 'health'
                                                ? '#4ade80'
                                                : '#60a5fa'
                                            );
                                          }
                                        } else {
                                          drop.bob += dt * 2;

                                          drop.group.position.y =
                                            drop.targetY + Math.sin(drop.bob) * 0.08;
                                        }

                                        drop.spin += dt;
                                        drop.group.rotation.y = drop.spin * 0.35;

                                        if (
                                          !drop.falling &&
                                          camera.position.distanceTo(drop.group.position) < 2.5
                                        ) {
                                          collectAirdrop(drop);
                                        }
                                      }

                                      airdrops = airdrops.filter(drop => !drop.collected);
                                    }

                              function positionOverlapsObstacle(
              position,
              radius,
              obstacle
            ) {
              if (!position || !obstacle || obstacle.blocksMovement === false) {
                return false;
              }

              const playerHalfHeight = 0.85;
              const playerMinY = position.y - playerHalfHeight;
              const playerMaxY = position.y + playerHalfHeight;

              const obstacleMinY = Number.isFinite(obstacle.minY) ? obstacle.minY : -Infinity;
              const obstacleMaxY = Number.isFinite(obstacle.maxY) ? obstacle.maxY : Infinity;

              const feetY = position.y - PLAYER_EYE_HEIGHT;
              const standingTolerance = 0.16;
              if (
                Number.isFinite(feetY) &&
                Number.isFinite(obstacleMaxY) &&
                Math.abs(feetY - obstacleMaxY) <= standingTolerance
              ) {
                return false;
              }

              if (playerMaxY < obstacleMinY || playerMinY > obstacleMaxY) {
                return false;
              }

              const closestX = THREE.MathUtils.clamp(position.x, obstacle.minX, obstacle.maxX);
              const closestZ = THREE.MathUtils.clamp(position.z, obstacle.minZ, obstacle.maxZ);
              const dx = position.x - closestX;
              const dz = position.z - closestZ;

              return dx * dx + dz * dz <= radius * radius;
            }

            function getStandingObstacleHeight(x, z, radius = PLAYER_RADIUS) {
              let best = 0;
              let bestObstacle = null;

              for (const obstacle of obstacles) {
                if (!obstacle || obstacle.blocksMovement === false) continue;
                if (!Number.isFinite(obstacle.maxY)) continue;

                const closestX = THREE.MathUtils.clamp(x, obstacle.minX, obstacle.maxX);
                const closestZ = THREE.MathUtils.clamp(z, obstacle.minZ, obstacle.maxZ);
                const dx = x - closestX;
                const dz = z - closestZ;

                const supportRadius = Math.max(0.05, radius + 0.12);
                if (dx * dx + dz * dz > supportRadius * supportRadius) continue;

                if (obstacle.maxY > best) {
                  best = obstacle.maxY;
                  bestObstacle = obstacle;
                }
              }

              return { height: best, obstacle: bestObstacle };
            }
      function getCurrentArenaBounds() {
        return Math.max(
          22,
          Math.min(worldBounds, arenaShrinkRadius || worldBounds)
        );
      }

                           function isInsideWorldBounds(position, radius = 0) {
        if (!position) {
          return false;
        }

        const bounds = getCurrentArenaBounds();

        return (
          position.x >= -bounds + radius &&
          position.x <= bounds - radius &&
          position.z >= -bounds + radius &&
          position.z <= bounds - radius
        );
      }

            function enemyCanMoveTo(position, radius = 0.45) {
              if (!position || !isInsideWorldBounds(position, radius)) {
                return false;
              }

              const enemyHeight = Math.max(1, radius * 2.2);

              for (const obstacle of obstacles) {
                if (!obstacle || obstacle.blocksMovement === false) {
                  continue;
                }

                const horizontalInside =
                  position.x >= obstacle.minX - radius &&
                  position.x <= obstacle.maxX + radius &&
                  position.z >= obstacle.minZ - radius &&
                  position.z <= obstacle.maxZ + radius;

                if (!horizontalInside) {
                  continue;
                }

                const enemyBottom = position.y;
                const enemyTop = position.y + enemyHeight;

                const standingOnTop =
                  Math.abs(enemyBottom - obstacle.maxY) <= 0.12;

                if (standingOnTop) {
                  continue;
                }

                const overlapsVertically =
                  enemyTop > obstacle.minY &&
                  enemyBottom < obstacle.maxY;

                if (overlapsVertically) {
                  return false;
                }
              }

              return true;
            }

                        function enemyCanSpawnAt(position, radius = 1) {
                          if (!isInsideWorldBounds(position, radius)) {
                            return false;
                          }

                          for (const obstacle of obstacles) {
                            if (positionOverlapsObstacle(position, radius, obstacle)) {
                              return false;
                            }
                          }

                          return true;
                        }

                     function canMoveTo(
              position,
              radius = PLAYER_RADIUS
            ) {
              if (
                !position ||
                !isInsideWorldBounds(position, radius)
              ) {
                return false;
              }

              for (const obstacle of obstacles) {
                if (
                  obstacle.blocksMovement === false ||
                  (vaulting && obstacle === vaultObstacle)
                ) {
                  continue;
                }

                if (
                  positionOverlapsObstacle(
                    position,
                    radius,
                    obstacle
                  )
                ) {
                  return false;
                }
              }

              return true;
            }
            function isLookingUp() {
              const direction = new THREE.Vector3();
              camera.getWorldDirection(direction);

              return direction.y >= WALL_CLIMB_LOOK_THRESHOLD;
            }

            function getClosestPointOnObstacleXZ(position, obstacle) {
              return new THREE.Vector3(
                THREE.MathUtils.clamp(position.x, obstacle.minX, obstacle.maxX),
                position.y,
                THREE.MathUtils.clamp(position.z, obstacle.minZ, obstacle.maxZ)
              );
            }

            function getWallContact() {
              const playerFeetY = camera.position.y - PLAYER_EYE_HEIGHT;
              const playerHeadY = playerFeetY + PLAYER_EYE_HEIGHT;

              let closestContact = null;
              let closestDistance = Infinity;

              for (const obstacle of obstacles) {
                if (!obstacle || obstacle.blocksMovement === false) {
                  continue;
                }

                const verticallyOverlapping =
                  playerHeadY > obstacle.minY &&
                  playerFeetY < obstacle.maxY;

                if (!verticallyOverlapping) {
                  continue;
                }

                const closestPoint = getClosestPointOnObstacleXZ(
                  camera.position,
                  obstacle
                );

                const offset = new THREE.Vector3(
                  camera.position.x - closestPoint.x,
                  0,
                  camera.position.z - closestPoint.z
                );

                const distance = offset.length();

                if (
                  distance <= PLAYER_RADIUS + WALL_CONTACT_DISTANCE &&
                  distance < closestDistance
                ) {
                  let normal;

                  if (distance > 0.0001) {
                    normal = offset.normalize();
                  } else {

                    const distances = [
                      {
                        distance: Math.abs(camera.position.x - obstacle.minX),
                        normal: new THREE.Vector3(-1, 0, 0)
                      },
                      {
                        distance: Math.abs(camera.position.x - obstacle.maxX),
                        normal: new THREE.Vector3(1, 0, 0)
                      },
                      {
                        distance: Math.abs(camera.position.z - obstacle.minZ),
                        normal: new THREE.Vector3(0, 0, -1)
                      },
                      {
                        distance: Math.abs(camera.position.z - obstacle.maxZ),
                        normal: new THREE.Vector3(0, 0, 1)
                      }
                    ];

                    distances.sort((a, b) => a.distance - b.distance);
                    normal = distances[0].normal;
                  }

                  closestDistance = distance;

                  closestContact = {
                    obstacle,
                    normal
                  };
                }
              }

              return closestContact;
            }

            function canWallClimb() {
              if (
                !alive ||
                dying ||
               !hasGameplayInput()||
                !jumpHeld
              ) {
                return null;
              }

              const contact = getWallContact();

              if (!contact || contact.obstacle?.climbable === false) {
                return null;
              }

              return contact;
            }

            function getRampTopHeight(x, z) {
              let highestRampHeight = 0;

              for (const ramp of ramps) {
                const inverseRotation = -ramp.rotation;

                const dx = x - ramp.x;
                const dz = z - ramp.z;

                const localX =
                  dx * Math.cos(inverseRotation) -
                  dz * Math.sin(inverseRotation);

                const localZ =
                  dx * Math.sin(inverseRotation) +
                  dz * Math.cos(inverseRotation);

                if (
                  Math.abs(localX) > ramp.width / 2 ||
                  Math.abs(localZ) > ramp.length / 2
                ) {
                  continue;
                }

                const progress =
                  (localZ + ramp.length / 2) / ramp.length;

                const height = THREE.MathUtils.clamp(
                  progress * ramp.height,
                  0,
                  ramp.height
                );

                highestRampHeight = Math.max(
                  highestRampHeight,
                  height
                );
              }

              return highestRampHeight;
            }

            function pointInsideObstacleXZ(x, z, obstacle, padding = 0) {
              return (
                x >= obstacle.minX - padding &&
                x <= obstacle.maxX + padding &&
                z >= obstacle.minZ - padding &&
                z <= obstacle.maxZ + padding
              );
            }
            function getEnemySurfaceHeight(x, z) {
              let surfaceHeight = 0;

              surfaceHeight = Math.max(
                surfaceHeight,
                getRampTopHeight(x, z)
              );

              for (const obstacle of obstacles) {
                if (!obstacle || obstacle.blocksMovement === false) {
                  continue;
                }

                const insideObstacle =
                  x >= obstacle.minX &&
                  x <= obstacle.maxX &&
                  z >= obstacle.minZ &&
                  z <= obstacle.maxZ;

                if (insideObstacle) {
                  surfaceHeight = Math.max(
                    surfaceHeight,
                    obstacle.maxY
                  );
                }
              }

              return surfaceHeight;
            }

            function getWalkableSurfaceHeight(x, z, currentFeetY = null) {
              let highestSurface = Math.max(0, getRampTopHeight(x, z));

              const feetKnown = Number.isFinite(currentFeetY);
              const supportTolerance = 0.20;

              for (const obstacle of obstacles) {
                if (!obstacle || obstacle.blocksMovement === false || !Number.isFinite(obstacle.maxY)) continue;

                const nx = THREE.MathUtils.clamp(x, obstacle.minX, obstacle.maxX);
                const nz = THREE.MathUtils.clamp(z, obstacle.minZ, obstacle.maxZ);
                const dx = x - nx;
                const dz = z - nz;
                const supportRadius = Math.max(0.05, PLAYER_RADIUS + 0.12);
                if (dx * dx + dz * dz > supportRadius * supportRadius) continue;

                if (feetKnown) {

                  if (currentFeetY < obstacle.maxY - supportTolerance) continue;
                }

                highestSurface = Math.max(highestSurface, obstacle.maxY);
              }

              return highestSurface;
            }

