                          const forward = new THREE.Vector3();
                          camera.getWorldDirection(forward);
                          forward.y = 0;

                          if (forward.lengthSq() === 0) {
                            forward.set(0, 0, -1);
                          } else {
                            forward.normalize();
                          }

                          const right = new THREE.Vector3(
                            -forward.z,
                            0,
                            forward.x
                          );

                          return forward
                            .multiplyScalar(inputForward / inputLength)
                            .add(
                              right.multiplyScalar(inputSide / inputLength)
                            )
