                                      const cost = rerollUsed ? REROLL_COST : 0;
                                      const canAfford = coins >= cost;

                                      button.textContent = cost === 0
                                        ? 'REROLL — FREE'
                                        : `REROLL — ${cost} COINS`;

                                      button.disabled = !canAfford;
