                        function tryEnemyParry(enemy, projectile = null) {
                          if (
                            !enemy ||
                            !enemy.alive ||
                            !enemy.sentinel ||
                            !enemy.mesh
                          ) {
                            return false;
                          }

                          if ((enemy.parryCooldown || 0) > 0) {
                            return false;
                          }

                          const distanceToPlayer =
                            enemy.mesh.position.distanceTo(camera.position);

                          if (
                            distanceToPlayer < SENTINEL_PARRY_MIN_DISTANCE ||
                            distanceToPlayer > SENTINEL_PARRY_MAX_DISTANCE
                          ) {
                            return false;
                          }

                          const chance = THREE.MathUtils.clamp(
                            enemy.dynamicParryChance ?? enemy.parryChance ?? 0,
                            0,
                            0.9
                          );

                          if (Math.random() >= chance) {
                            return false;
                          }

                          enemy.parryCooldown = SENTINEL_PARRY_COOLDOWN;
                          enemy.parryWindow = 0.22;
                          enemy.lastParryTime = performance.now();
                          enemy.parryCount++;

                          showFeed('SENTINEL PARRIED!', '#22d3ee');
                          window.playSound('melee', 0.9, 1.25);

                          if (!projectile) {
                            return true;
                          }

                          if (
                            !projectile.mesh ||
                            !projectile.vel ||
                            projectile.owner !== 'player'
                          ) {
                            return true;
                          }

                          const reflectedDirection = camera.position
                            .clone()
                            .sub(enemy.mesh.position)
                            .normalize();

                          const speed = Math.max(
                            SENTINEL_PARRY_SPEED,
                            projectile.vel.length() * 1.15
                          );

                          projectile.vel.copy(
                            reflectedDirection.multiplyScalar(speed)
                          );

                          projectile.owner = 'enemy';
                          projectile.enemy = null;
                          projectile.weapon = null;
                          projectile.parried = true;

                          projectile.damage = Math.max(
                            1,
                            projectile.damage * SENTINEL_PARRY_DAMAGE_MULTIPLIER
                          );

                          projectile.hitEnemies = new Set([enemy]);

                          if (projectile.mesh.material?.color) {
                            projectile.mesh.material.color.setHex(0x22d3ee);
                          }

                          if (projectile.mesh.material?.emissive) {
                            projectile.mesh.material.emissive.setHex(0x0891b2);
                            projectile.mesh.material.emissiveIntensity = 4;
                          }

                          return true;
                        }

                      function hitEnemy(
        enemy,
        damage,
        weapon = null,
        hitInfo = null
      ) {
        if (
          !enemy ||
          !enemy.alive ||
          !Number.isFinite(damage)
        ) {
          return;
        }

        let finalDamage = Math.max(0, damage);
      if (weapon) {
        registerWeaponHit(enemy);
        finalDamage = getWeaponAbilityDamageMultiplier(enemy, finalDamage);
      }
        finalDamage *= getPlayerDamageMultiplier();
        finalDamage *= getActiveDamageMult();

        finalDamage = applyExecutionerDamage(
          enemy,
          finalDamage
        );

        if (enemy.shieldbearer && enemy.shielded) {
          finalDamage *= 0.15;
        }

        const isHeadshot =
          hitInfo?.headshot === true ||
          enemy.lastHitWasHeadshot === true;

        if (isHeadshot) {
          finalDamage *=
            weapon?.headshotMultiplier ??
            weapon?.headshotDamage ??
            weapon?.headshotMultiplier ??
            HEADSHOT_MULTIPLIER;

          showFeed(
            `HEADSHOT! ${Math.floor(finalDamage)} DAMAGE`,
            '#facc15'
          );
        }

        const critBonus = getActiveCritBonus();

        const critChance = Math.min(
          0.95,
          (weapon?.critChance ?? 0) + critBonus
        );

        if (
          weapon &&
          critChance > 0 &&
          Math.random() < critChance
        ) {
          /*
           * Support both names used by the weapon definitions:
           * critMultiplier and critDamage.
           */
          const critMultiplier =
            weapon.critMultiplier ??
            weapon.critDamage ??
            2.25;

          finalDamage *= critMultiplier;

          showFeed(
            `CRITICAL HIT! ${Math.floor(finalDamage)} DAMAGE`,
            '#facc15'
          );
        }

        const previousHp = Math.max(
          0,
          Number.isFinite(enemy.hp) ? enemy.hp : 0
        );

        const deathPosition = enemy.mesh?.position?.clone() || null;

        enemy.hp = previousHp - finalDamage;

        playCombatAnimation(
          enemy.hp <= 0 ? 'kill' : 'hit'
        );

        applyPlayerLifeSteal(finalDamage);

        const lifeSteal = getLifeStealPercent();

        if (lifeSteal > 0 && finalDamage > 0) {
          hp = Math.min(
            getMaxHealth(),
            hp + finalDamage * lifeSteal
          );

          updateHealthHud();
        }

        window.playSound('enemyHurt', 0.6, 1.1);

        flashEnemy(enemy);

        if (weapon) {
          applyWeaponEffect(enemy, weapon);
          applyWeaponSpecialEffects(enemy, finalDamage, weapon);
        }

        enemy.lastHitWasHeadshot = false;

        if (enemy.hp <= 0) {
          /*
           * Calculate excess damage before killEnemy() removes the mesh.
           */
          const overkillDamage = Math.max(
            0,
            finalDamage - previousHp
          );

          killEnemy(enemy);

          /*
           * Only the original hit may start an overkill chain.
           * Chained hits must not recursively create more chains.
           */
          if (
            !hitInfo?.overkillChain &&
            overkillDamage > 0 &&
            deathPosition
          ) {
            applyOverkillChain(
              deathPosition,
              overkillDamage,
              weapon
            );
          }

          if (weapon?.uniqueAbility === 'soulHarvest') {
            const healingAmount = 8;

            hp = Math.min(
              getMaxHealth(),
              hp + healingAmount
            );

            updateHealthHud();

            showFeed(
              `SOUL HARVEST +${healingAmount} HP`,
              '#c084fc'
            );
          }
        }
      }


