                                   function segmentSphereHit(start, end, center, radius) {
                                const segment = end.clone().sub(start);
                                const segmentLengthSquared = segment.lengthSq();

                                if (segmentLengthSquared <= 0.000001) {
                                  return start.distanceTo(center) <= radius;
                                }

                                const projection = center.clone().sub(start).dot(segment);
                                const t = THREE.MathUtils.clamp(
                                  projection / segmentLengthSquared,
                                  0,
                                  1
                                );

                                const closestPoint = start.clone().addScaledVector(segment, t);

                                return closestPoint.distanceTo(center) <= radius;
                              }
                              function segmentSphereEntry(start, end, center, radius) {
                          const direction = end.clone().sub(start);
                          const offset = start.clone().sub(center);

                          const a = direction.dot(direction);

                          if (a <= 0.000001) {
                            return start.distanceTo(center) <= radius ? 0 : null;
                          }

                          const b = 2 * offset.dot(direction);
                          const c = offset.dot(offset) - radius * radius;
                          if (c <= 0) {
                            return 0;
                          }
                          const discriminant = b * b - 4 * a * c;

                          if (discriminant < 0) {
                            return null;
                          }

                          const squareRoot = Math.sqrt(discriminant);

                          const t1 = (-b - squareRoot) / (2 * a);
                          const t2 = (-b + squareRoot) / (2 * a);

                          const validHits = [t1, t2].filter(
                            t => t >= 0 && t <= 1
                          );

                          return validHits.length > 0
                            ? Math.min(...validHits)
                            : null;
                        }

                        function segmentIntersectsAABB(start, end, box, padding = 0) {
                          const min = box.min.clone().addScalar(-padding);
                          const max = box.max.clone().addScalar(padding);

                          const direction = end.clone().sub(start);

                          let tMin = 0;
                          let tMax = 1;

                          for (const axis of ['x', 'y', 'z']) {
                            const origin = start[axis];
                            const delta = direction[axis];

                            if (Math.abs(delta) < 0.000001) {
                              if (origin < min[axis] || origin > max[axis]) {
                                return false;
                              }

                              continue;
                            }

                            let t1 = (min[axis] - origin) / delta;
                            let t2 = (max[axis] - origin) / delta;

                            if (t1 > t2) {
                              [t1, t2] = [t2, t1];
                            }

                            tMin = Math.max(tMin, t1);
                            tMax = Math.min(tMax, t2);

                            if (tMin > tMax) {
                              return false;
                            }
                          }

                          return true;
                        }

                        function segmentAABBEntry(start, end, min, max, padding = 0) {
                          const expandedMin = min.clone().addScalar(-padding);
                          const expandedMax = max.clone().addScalar(padding);

                          const direction = end.clone().sub(start);

                          let tMin = 0;
                          let tMax = 1;

                          for (const axis of ['x', 'y', 'z']) {
                            const origin = start[axis];
                            const delta = direction[axis];

                            if (Math.abs(delta) < 0.000001) {
                              if (
                                origin < expandedMin[axis] ||
                                origin > expandedMax[axis]
                              ) {
                                return null;
                              }

                              continue;
                            }

                            let t1 = (expandedMin[axis] - origin) / delta;
                            let t2 = (expandedMax[axis] - origin) / delta;

                            if (t1 > t2) {
                              [t1, t2] = [t2, t1];
                            }

                            tMin = Math.max(tMin, t1);
                            tMax = Math.min(tMax, t2);

                            if (tMin > tMax) {
                              return null;
                            }
                          }

                          return tMin;
                        }

                        function getEnemyModelHit(enemy, start, end, projectileRadius = 0) {
                          if (
                            !enemy ||
                            !enemy.alive ||
                            !enemy.mesh
                          ) {
                            return null;
                          }

                          enemy.mesh.updateMatrixWorld(true);

                          let bestHit = null;

                          const inverseBodyMatrix = enemy.mesh.matrixWorld.clone().invert();

                          const localStart = start.clone().applyMatrix4(inverseBodyMatrix);
                          const localEnd = end.clone().applyMatrix4(inverseBodyMatrix);

                          const halfSize = enemy.size * 0.5;

                          const bodyMin = new THREE.Vector3(
                            -halfSize,
                            0,
                            -halfSize
                          );

                          const bodyMax = new THREE.Vector3(
                            halfSize,
                            enemy.size * 2,
                            halfSize
                          );

                          const bodyEntry = segmentAABBEntry(
                            localStart,
                            localEnd,
                            bodyMin,
                            bodyMax,
                            projectileRadius
                          );

                          if (bodyEntry !== null) {
                            bestHit = {
                              t: bodyEntry,
                              headshot: false,
                              part: 'body'
                            };
                          }

                          if (
                            enemy.head &&
                            enemy.head.visible &&
                            !enemy.cloaked
                          ) {
                            enemy.head.updateMatrixWorld(true);

                            const headCenter = enemy.head.getWorldPosition(
                              new THREE.Vector3()
                            );

                            const headScale = enemy.head.getWorldScale(
                              new THREE.Vector3()
                            );

                            const headRadius =
                              enemy.size *
                              0.58 *
                              Math.max(
                                headScale.x,
                                headScale.y,
                                headScale.z
                              ) +
                              projectileRadius;

                            const headEntry = segmentSphereEntry(
                              start,
                              end,
                              headCenter,
                              headRadius
                            );

                            if (
                              headEntry !== null &&
                              (
                                bestHit === null ||
                                headEntry < bestHit.t
                              )
                            ) {
                              bestHit = {
                                t: headEntry,
                                headshot: true,
                                part: 'head'
                              };
                            }
                          }

                          return bestHit;
                        }
      function isMobileViewport() {
        return Boolean(
          window.matchMedia(
            '(hover: none) and (pointer: coarse), (max-width: 700px)'
          ).matches
        );
      }

      function getMobileCrosshairTarget() {
        if (!alive || dying || !isMobileViewport()) {
          return null;
        }

        const selectedKey = loadout[selected];
        const weapon = selectedKey ? W[selectedKey] : null;

        if (!weapon || weapon.medkit || weapon.bandage) {
          return null;
        }

        const range = Number.isFinite(weapon.range)
          ? weapon.range
          : 100;

        const forward = new THREE.Vector3();
        camera.getWorldDirection(forward);
        forward.normalize();

        let bestEnemy = null;
        let bestScore = -Infinity;

        for (const enemy of enemies) {
          if (
            !enemy ||
            !enemy.alive ||
            !enemy.mesh ||
            !isFiniteVector3(enemy.mesh.position)
          ) {
            continue;
          }

          const toEnemy = enemy.mesh.position
            .clone()
            .sub(camera.position);

          const distance = toEnemy.length();

          if (distance <= 0.001 || distance > range) {
            continue;
          }

          toEnemy.normalize();

          const alignment = forward.dot(toEnemy);

          if (alignment < 0.975) {
            continue;
          }

          if (!enemyVisibleFromPlayer(enemy, range)) {
            continue;
          }

          const score = alignment * 1000 - distance;

          if (score > bestScore) {
            bestScore = score;
            bestEnemy = enemy;
          }
        }

        return bestEnemy;
      }

