      function updateWaveElevator() {
        const elevator = $('waveElevator');
        const button = $('waveElevatorBtn');
        const text = $('waveElevatorText');
        const costElement = $('waveElevatorCost');
        const range = $('waveElevatorRange');
        const selectedWaveElement = $('waveElevatorSelectedWave');
        const currentWaveElement = $('waveElevatorCurrentWave');
        const highestWaveElement = $('waveElevatorHighestWave');
        const hint = $('waveElevatorHint');

        if (
          !elevator ||
          !button ||
          !text ||
          !costElement ||
          !range ||
          !selectedWaveElement ||
          !currentWaveElement ||
          !highestWaveElement ||
          !hint
        ) {
          return;
        }

        updateHighestWaveReached();

        const deathScreenVisible =
          loadoutMode === 'death' &&
          $('death')?.classList.contains('show');

        const highest = Math.max(
          1,
          Math.floor(Number(highestWaveReached) || 1)
        );

        elevatorTargetWave = THREE.MathUtils.clamp(
          Math.floor(Number(elevatorTargetWave) || 1),
          1,
          highest
        );

        const visible = deathScreenVisible && highest >= 2;

        elevator.hidden = !visible;

        if (!visible) {
          return;
        }

        const selectedWave = getElevatorTargetWave();
        const cost = getWaveElevatorCost(selectedWave);

        range.min = '1';
        range.max = String(highest);
        range.value = String(selectedWave);
        range.disabled = elevatorUsed;

        currentWaveElement.textContent =
          `CURRENT WAVE ${Math.max(1, wave)}`;

        highestWaveElement.textContent =
          `HIGHEST WAVE ${highest}`;

        selectedWaveElement.textContent =
          `WAVE ${selectedWave}`;

        costElement.textContent =
          selectedWave <= 1
            ? 'Cost: —'
            : `Cost: ${cost.toLocaleString()} coins`;

        if (elevatorUsed) {
          text.textContent =
            `The elevator has already been used. You are queued for Wave ${selectedWave}.`;

          button.disabled = true;
          button.textContent = 'ELEVATOR USED';
          hint.textContent =
            'This elevator can only be used once per run.';

          return;
        }

        text.textContent =
          `Choose any wave from 2 to ${highest}. Higher starting waves cost more coins.`;

        if (selectedWave <= 1) {
          button.disabled = true;
          button.textContent = 'SELECT A WAVE';
          hint.textContent = 'Choose a wave above Wave 1.';
          return;
        }

        if (coins < cost) {
          button.disabled = true;
          button.textContent = 'NOT ENOUGH COINS';
          hint.textContent =
            `You need ${(cost - coins).toLocaleString()} more coins.`;

          return;
        }

        button.disabled = false;
        button.textContent = `GO TO WAVE ${selectedWave}`;
        hint.textContent =
          `This will cost ${cost.toLocaleString()} coins.`;
      }

      function useWaveElevator() {
        if (
          loadoutMode !== 'death' ||
          elevatorUsed ||
          !$('death')?.classList.contains('show')
        ) {
          return;
        }

        updateHighestWaveReached();

        const targetWave = getElevatorTargetWave();
        const cost = getWaveElevatorCost(targetWave);

        if (targetWave <= 1) {
          showFeed('SELECT A WAVE ABOVE WAVE 1', '#facc15');
          return;
        }

        if (coins < cost) {
          showFeed(
            `NOT ENOUGH COINS — NEED ${cost.toLocaleString()}`,
            '#fca5a5'
          );

          updateWaveElevator();
          return;
        }

        coins -= cost;
        elevatorTargetWave = targetWave;
        elevatorUsed = true;

        updateGameHud();
        updateWaveElevator();
        saveGame();

        showFeed(
          `ELEVATOR READY — WAVE ${targetWave}`,
          '#facc15'
        );
      }

