      function renderHealthVisual(currentHealth, maxHealth, ratio) {
        const hpElement = $('hp');
        const hpFillElement = $('hpFill');
        const hpGhostElement = $('hpDamageGhost');
        const healthBar = $('healthBar');
        const healthHud = $('top');
        const percentElement = $('healthPercent');
        const statusElement = $('healthStatus');
        const healthVignette = $('healthVignette');

        const safeRatio = THREE.MathUtils.clamp(ratio, 0, 1);
        const percent = Math.round(safeRatio * 100);

        let state = 'healthy';
        let status = 'HEALTHY';

        if (safeRatio <= 0) {
          state = 'empty';
          status = 'DOWN';
        } else if (safeRatio <= 0.25) {
          state = 'critical';
          status = 'CRITICAL';
        } else if (safeRatio <= 0.55) {
          state = 'warning';
          status = 'WARNING';
        }

        if (hpElement) {
          hpElement.textContent =
            `HP ${Math.ceil(currentHealth)} / ${Math.ceil(maxHealth)}`;
        }

        if (percentElement) {
          percentElement.textContent = `${percent}%`;
        }

        if (statusElement) {
          statusElement.textContent = status;
        }

        if (healthHud) {
          healthHud.dataset.healthState = state;
          healthHud.style.setProperty('--health-ratio', safeRatio.toFixed(4));
        }

        if (hpFillElement) {
          hpFillElement.style.width = `${safeRatio * 100}%`;
        }

        if (hpGhostElement) {
          hpGhostElement.style.width = `${safeRatio * 100}%`;
        }

        if (healthBar) {
          healthBar.setAttribute('aria-valuenow', String(percent));
          healthBar.setAttribute(
            'aria-valuetext',
            `${Math.ceil(currentHealth)} of ${Math.ceil(maxHealth)} health`
          );
        }

        if (healthVignette) {
          const dangerAmount = 1 - safeRatio;
          const vignetteStrength = Math.pow(dangerAmount, 1.35);

          healthVignette.style.setProperty(
            '--health-danger',
            vignetteStrength.toFixed(3)
          );

          healthVignette.classList.toggle(
            'critical',
            safeRatio <= 0.25 && currentHealth > 0
          );
        }
      }

      function animateHealthHud(timestamp) {
        if (!healthLastAnimationTime) {
          healthLastAnimationTime = timestamp;
        }

        const deltaTime = Math.min(
          0.05,
          Math.max(0, (timestamp - healthLastAnimationTime) / 1000)
        );

        healthLastAnimationTime = timestamp;

        const { currentHealth, maxHealth } = getSafeHealthValues();

        const smoothing = 1 - Math.exp(-deltaTime * 14);

        displayedHealth +=
          (currentHealth - displayedHealth) * smoothing;

        if (Math.abs(displayedHealth - currentHealth) < 0.05) {
          displayedHealth = currentHealth;
        }

        renderHealthVisual(
          displayedHealth,
          maxHealth,
          displayedHealth / maxHealth
        );

        if (Math.abs(displayedHealth - currentHealth) >= 0.05) {
          healthAnimationFrame =
            requestAnimationFrame(animateHealthHud);
        } else {
          healthAnimationFrame = 0;
        }
      }

      function updateHealthHud({ immediate = false } = {}) {
        const { currentHealth, maxHealth, ratio } =
          getSafeHealthValues();

        if (immediate || !Number.isFinite(displayedHealth)) {
          displayedHealth = currentHealth;

          if (healthAnimationFrame) {
            cancelAnimationFrame(healthAnimationFrame);
            healthAnimationFrame = 0;
          }

          renderHealthVisual(
            displayedHealth,
            maxHealth,
            displayedHealth / maxHealth
          );

          return;
        }

        renderHealthVisual(
          displayedHealth,
          maxHealth,
          displayedHealth / maxHealth
        );

        if (!healthAnimationFrame) {
          healthLastAnimationTime = performance.now();
          healthAnimationFrame =
            requestAnimationFrame(animateHealthHud);
        }
      }

