                                  function chooseRoundModifier() {
                          if (wave < 2) {
                            activeRoundModifier = null;
                            updateRoundModifierHud();
                            applyPlayerMaxHealth();
                            return;
                          }

                          const modifiers = Object.values(ROUND_MODIFIERS);

                          activeRoundModifier =
                            modifiers[Math.floor(Math.random() * modifiers.length)];

                          applyPlayerMaxHealth();
                          showRoundModifier();
                        }

                                    function showAbilitySelect() {
                                      if (!ownedAbilities.length) {
                                        activeAbilities = [];
                                        setOverlay('abilitySelect', false);
                                        return;
                                      }

                                      const uniqueOwned = Array.from(
                                        new Set(ownedAbilities)
                                      );

                                      if (!activeAbilities.length) {
                                        activeAbilities = uniqueOwned.slice(0, 3);
                                      } else {
                                        activeAbilities = activeAbilities
                                          .filter(id => uniqueOwned.includes(id))
                                          .slice(0, 3);
                                      }

                                      renderAbilitySelectionUI();
                                      setOverlay('abilitySelect', true);
                                    }
                                    function hasActiveAbility(id) {
                                return activeAbilities.includes(id) &&
                                  getStackCount(id) > 0;
                              }

                             function tryEmergencyBlink(incomingDamage) {
                          const maxHealth = getMaxHealth();

                          if (
                            !hasActiveAbility('emergencyBlink') ||
                            emergencyBlinkUsed ||
                            hp - incomingDamage > 0
                          ) {
                            return false;
                          }

                          emergencyBlinkUsed = true;
                          hp = 1;

                          let teleported = false;

                          for (let attempt = 0; attempt < 20; attempt++) {
                            const angle = Math.random() * Math.PI * 2;
                            const distance = 7 + Math.random() * 6;

                            const destination = camera.position.clone();

                            destination.x += Math.cos(angle) * distance;
                            destination.z += Math.sin(angle) * distance;

                            destination.x = THREE.MathUtils.clamp(
                              destination.x,
                              -worldBounds + PLAYER_RADIUS,
                              worldBounds - PLAYER_RADIUS
                            );

                            destination.z = THREE.MathUtils.clamp(
                              destination.z,
                              -worldBounds + PLAYER_RADIUS,
                              worldBounds - PLAYER_RADIUS
                            );

                            if (canMoveTo(destination, PLAYER_RADIUS)) {
                              camera.position.x = destination.x;
                              camera.position.z = destination.z;
                              teleported = true;
                              break;
                            }
                          }

                          showFeed(
                            teleported
                              ? 'EMERGENCY BLINK ACTIVATED'
                              : 'EMERGENCY BLINK SAVED YOU',
                            '#c084fc'
                          );

                          window.playSound('pickup');
                          updateHealthHud();

                          return true;
                        }

                              function fireEchoShot(weapon) {
                                if (!weapon || weapon.melee || weapon.medkit || weapon.bandage) {
                                  return;
                                }

                                const direction = new THREE.Vector3();
                                camera.getWorldDirection(direction);

                                const echoWeapon = {
                                  ...weapon,
                                  damage: weapon.damage * 0.45,
                                  range: weapon.range
                                };

                                shot(direction, echoWeapon);
                                showFeed('ECHO SHOT', '#67e8f9');
                              }

                                    function renderAbilitySelectionUI() {
                                      const container = $('abilityButtons');
                                      container.innerHTML = '';

                                      const uniqueOwned = Array.from(new Set(ownedAbilities));

                                      $('activeAbilitiesCount').textContent = activeAbilities.length.toString();

                                      if (uniqueOwned.length === 0) {
                                        container.innerHTML = `<div style="opacity:.8">Buy abilities from the shop first.</div>`;
                                        return;
                                      }

                                      for (const id of uniqueOwned) {
                                        const def = ABILITY_CATALOG[id];
                                        const ownedStacks = getStackCount(id);
                                        const active = activeAbilities.includes(id);

                                        const btn = document.createElement('button');
                                        btn.className = 'continue';
                                        btn.style.background = active
                                          ? 'linear-gradient(90deg,#2563eb,#22c55e)'
                                          : 'rgba(148,163,184,.25)';
                                        btn.style.color = active ? 'white' : '#e5e7eb';
                                        btn.style.padding = '12px';
                                        btn.style.fontWeight = '900';
                                        btn.style.fontSize = '13px';

                                        btn.textContent = `${def.icon} ${def.name} (x${ownedStacks})`;

                                        btn.onclick = () => {
                                          if (active) {

                                            activeAbilities = activeAbilities.filter(x => x !== id);
                                          } else {

                                            if (activeAbilities.length >= 3) return;
                                            activeAbilities.push(id);
                                          }
                                          renderAbilitySelectionUI();
                                        };

                                        container.appendChild(btn);
                                      }
                                    }

