            function tutorialWasSeen(){try{return localStorage.getItem(TUTORIAL_STORAGE_KEY)==='1';}catch(_){return false;}}
            function markTutorialSeen(){try{localStorage.setItem(TUTORIAL_STORAGE_KEY,'1');}catch(_){} }
            function clearTutorialHighlights(){document.querySelectorAll('.tutorial-target').forEach(el=>el.classList.remove('tutorial-target'));}
            function tutorialStatus(text){let el=document.getElementById('tutorialLiveStatus');if(!el){el=document.createElement('div');el.id='tutorialLiveStatus';el.className='tutorial-live-status';document.querySelector('.tutorial-card')?.appendChild(el);}if(el)el.textContent=text||'';}
            function renderTutorialStep(){
              const step=tutorialSteps[tutorialStep];
              if(!step){finishTutorial();return;}
              clearTutorialHighlights();
              $('tutorialKicker').textContent=`LIVE TUTORIAL • ${tutorialStep+1}/${tutorialSteps.length}`;
              $('tutorialTitle').textContent=step.title;
              $('tutorialText').textContent=step.text;
              $('tutorialIcon').textContent=step.icon;
              $('tutorialVisualTitle').textContent=step.visualTitle;
              $('tutorialVisualText').textContent=step.visualText;
              $('tutorialMouseBadge').textContent=step.badge;
              $('tutorialPage').textContent=`${tutorialStep+1} / ${tutorialSteps.length}`;
              $('tutorialProgressFill').style.width=`${((tutorialStep+1)/tutorialSteps.length)*100}%`;
              $('tutorialNext').textContent=step.action==='finish' ? 'START' : 'WAITING…';
              if(step.target) $(step.target)?.classList.add('tutorial-target');
              tutorialStepDone=false;
              tutorialMovedDistance=0;
              tutorialLastPos=camera.position.clone();
              tutorialStatus(step.action==='finish'?'PRESS ENTER TO BEGIN THE FIRST WAVE':'DO THE ACTION SHOWN ABOVE');
            }
            function trackTutorialObject(object) {
        if (object) {
          tutorialCourseObjects.push(object);
        }

        return object;
      }

      function trackTutorialObstacle(object) {
        if (!object) {
          return;
        }

        const obstacle = obstacles.find(item => item.mesh === object);

        if (obstacle && !tutorialCourseObstacles.includes(obstacle)) {
          tutorialCourseObstacles.push(obstacle);
        }

        trackTutorialObject(object);
      }

      function createTutorialCourse() {
        if (tutorialCourseCreated) {
          return;
        }

        tutorialCourseCreated = true;
        tutorialCourseObjects = [];
        tutorialCourseObstacles = [];
        tutorialCoursePads = [];

        const origin = camera.position.clone();
        const x = origin.x;
        const z = origin.z;

        trackTutorialObstacle(
          addObstacleBox(
            x,
            0,
            z - 8,
            6,
            1.1,
            2,
            concreteMat,
            {
              climbable: false,
              blocksMovement: true,
              blocksShots: true
            }
          )
        );

        trackTutorialObstacle(
          addObstacleBox(
            x + 10,
            0,
            z - 14,
            2,
            7,
            8,
            wallMat,
            {
              climbable: true,
              blocksMovement: true,
              blocksShots: true
            }
          )
        );

        trackTutorialObstacle(
          addObstacleBox(
            x - 10,
            0,
            z - 20,
            8,
            3,
            8,
            accentMat,
            {
              climbable: true,
              blocksMovement: true,
              blocksShots: true,
              parkourSurface: true
            }
          )
        );

        const previousPadCount = jumpPads.length;

        addJumpPad(
          x,
          z - 5,
          1.6,
          18,
          0x22d3ee
        );

        const pad = jumpPads[previousPadCount];

        if (pad) {
          tutorialCoursePads.push(pad);

          pad.mesh.userData.tutorialPad = true;
          pad.mesh.userData.tutorialOnly = true;
          pad.mesh.userData.tutorialHighlight = true;

          pad.ring.userData.tutorialPad = true;
          pad.ring.userData.tutorialOnly = true;
          pad.ring.userData.tutorialHighlight = true;
        }

        const grappleTarget = new THREE.Mesh(
          new THREE.BoxGeometry(3, 3, 0.5),
          new THREE.MeshStandardMaterial({
            color: 0x22d3ee,
            emissive: 0x0891b2,
            emissiveIntensity: 1.8
          })
        );

        grappleTarget.position.set(x + 15, 6, z - 25);
        grappleTarget.userData.grappleAnchor = true;
        grappleTarget.userData.tutorialOnly = true;

        scene.add(grappleTarget);
        trackTutorialObject(grappleTarget);
        trackTutorialObstacle(grappleTarget);

        const platforms = [
          [x - 12, z - 28, 5, 5, 4],
          [x - 4, z - 34, 5, 5, 6],
          [x + 6, z - 38, 5, 5, 8],
          [x + 16, z - 32, 5, 5, 5]
        ];

        for (const [px, pz, width, depth, height] of platforms) {
          trackTutorialObstacle(
            addObstacleBox(
              px,
              0,
              pz,
              width,
              height,
              depth,
              accentMat,
              {
                climbable: true,
                blocksMovement: true,
                blocksShots: true,
                parkourSurface: true
              }
            )
          );
        }
      }

      function removeTutorialCourse() {
        for (const obstacle of tutorialCourseObstacles) {
          const index = obstacles.indexOf(obstacle);

          if (index >= 0) {
            obstacles.splice(index, 1);
          }
        }

        for (const pad of tutorialCoursePads) {
          const index = jumpPads.indexOf(pad);

          if (index >= 0) {
            jumpPads.splice(index, 1);
          }

          if (pad.mesh) {
            removeObject(pad.mesh);
          }

          if (pad.ring) {
            removeObject(pad.ring);
          }
        }

        for (const object of tutorialCourseObjects) {
          if (
            object &&
            object.parent &&
            !tutorialCoursePads.some(
              pad => pad.mesh === object || pad.ring === object
            )
          ) {
            removeObject(object);
          }
        }

        tutorialCourseObjects = [];
        tutorialCourseObstacles = [];
        tutorialCoursePads = [];
        tutorialCourseCreated = false;
      }

        function startTutorial() {
        if (tutorialWasSeen()) {
          return false;
        }

        tutorialActive = true;
        tutorialStep = 0;
        tutorialStepDone = false;
        tutorialMovedDistance = 0;
        tutorialLastPos = null;

        window.__tutorialPadTriggered = false;
        window.__tutorialGrappleTriggered = false;

        createTutorialCourse();
        renderTutorialStep();
        setOverlay('tutorialOverlay', true);

        return true;
      }

        function finishTutorial() {
        markTutorialSeen();

        tutorialActive = false;
        window.__tutorialPadTriggered = false;
        window.__tutorialGrappleTriggered = false;

        removeTutorialCourse();

        waveTimer = 0;
        waveSpawning = false;

        clearTutorialHighlights();
        setOverlay('tutorialOverlay', false);
        tutorialStatus('');

        updateGameHud();

        if (tutorialWaveDeferred && alive && !dying) {
          tutorialWaveDeferred = false;
          startWave();
        }
      }

      function tutorialRegisterGrapple() {
        if (!tutorialActive || tutorialStepDone) {
          return;
        }

        if (tutorialSteps[tutorialStep]?.action === 'grapple') {
          tutorialRegisterAction('grapple');
        }
      }

            function completeTutorialStep(message){
              if(!tutorialActive||tutorialStepDone)return;
              tutorialStepDone=true;tutorialStatus(`✓ ${message}`);
              $('tutorialNext').textContent = tutorialStep >= tutorialSteps.length - 1 ? 'START' : 'NEXT';
              setTimeout(()=>{if(!tutorialActive||!tutorialStepDone)return;if(tutorialStep>=tutorialSteps.length-1){finishTutorial();return;}tutorialStep++;renderTutorialStep();},420);
            }
           function tutorialRegisterAction(action) {
        if (!tutorialActive || tutorialStepDone) {
          return;
        }

        const step = tutorialSteps[tutorialStep];

        if (!step || step.action !== action) {
          return;
        }

      const names = {
        look: 'Looking learned',
        move: 'Movement learned',
        sprint: 'Sprinting learned',
        jump: 'Jump learned',
        slide: 'Sliding learned',
        vault: 'Vaulting learned',
        dash: 'Dashing learned',
        climb: 'Climbing learned',
        wall: 'Wall-jumping learned',
        pad: 'Jump pad learned',
        grapple: 'Grappling learned',
        shoot: 'Firing learned',
        aim: 'Aiming learned',
        reload: 'Reloading learned',
        weapon: 'Weapon switching learned',
        info: 'Information reviewed',
        finish: 'Ready'
      };

        completeTutorialStep(names[action] || 'Action complete');
      }
      window.__killshiftTutorialAction = action => {
        if (typeof tutorialRegisterAction === 'function') {
          tutorialRegisterAction(action);
        }
      };

        function updateTutorialTraining() {
        if (!tutorialActive || tutorialStepDone) {
          return;
        }

        if (tutorialLastPos) {
          tutorialMovedDistance += camera.position.distanceTo(tutorialLastPos);
        }

        tutorialLastPos = camera.position.clone();

        const step = tutorialSteps[tutorialStep];

        if (!step) {
          return;
        }

        if (
          step.action === 'move' &&
          tutorialMovedDistance > 0.75
        ) {
          tutorialRegisterAction('move');
        } else if (
          step.action === 'sprint' &&
          isSprintKeyDown() &&
          Math.hypot(moveVelocityX, moveVelocityZ) > WALK_SPEED * 1.05
        ) {
          tutorialRegisterAction('sprint');
        } else if (
          step.action === 'dash' &&
          dashActiveTime > 0
        ) {
          tutorialRegisterAction('dash');
        } else if (
          step.action === 'pad' &&
          window.__tutorialPadTriggered
        ) {
          window.__tutorialPadTriggered = false;
          tutorialRegisterAction('pad');
        } else if (
          step.action === 'wall' &&
          (
            wallRunning ||
            climbingWall ||
            wallJumpCooldown > 0.35
          )
        ) {
          tutorialRegisterAction('wall');
        } else if (
          step.action === 'grapple' &&
          window.__tutorialGrappleTriggered
        ) {
          window.__tutorialGrappleTriggered = false;
          tutorialRegisterAction('grapple');
        }
      }

            function bindTutorialControls(){
              const skipBtn = $('tutorialSkip');
              const backBtn = $('tutorialBack');
              const nextBtn = $('tutorialNext');

              if(skipBtn){
                skipBtn.onclick = () => {
                  finishTutorial();
                };
              }

              if(backBtn){
                backBtn.onclick = () => {
                  if(!tutorialActive) return;
                  if(tutorialStep > 0){
                    tutorialStep--;
                    renderTutorialStep();
                  }
                };
              }

              if(nextBtn){
                nextBtn.onclick = () => {
                  if(!tutorialActive) return;
                  if(tutorialSteps[tutorialStep]?.action === 'finish') {
                    finishTutorial();
                    return;
                  }
                  if(!tutorialStepDone){
                    tutorialRegisterAction(tutorialSteps[tutorialStep]?.action);
                    return;
                  }
                  if(tutorialStep < tutorialSteps.length - 1){
                    tutorialStep++;
                    renderTutorialStep();
                  } else {
                    finishTutorial();
                  }
                };
              }
            }

