              if(event.code==='Enter'&&tutorialSteps[tutorialStep]?.action==='finish'){event.preventDefault();finishTutorial();return;}
              if(event.code==='ArrowRight' && tutorialStep < tutorialSteps.length - 1 && tutorialStepDone){event.preventDefault();tutorialStep++;renderTutorialStep();return;}
              if(event.code==='ArrowLeft' && tutorialStep > 0){event.preventDefault();tutorialStep--;renderTutorialStep();return;}
              if(event.code==='KeyQ')tutorialRegisterAction('dash');
              if(event.code==='KeyF')tutorialRegisterAction('shoot');
              if(event.code==='KeyR')tutorialRegisterAction('reload');
              if(event.code==='ControlLeft'||event.code==='ControlRight'||event.code==='KeyC')tutorialRegisterAction('slide');
              if(event.code==='ShiftLeft'||event.code==='ShiftRight')tutorialRegisterAction('sprint');
              if(event.code==='Space'&&(wallRunning||climbingWall))tutorialRegisterAction('wall');
