                                    function updateSpecialWeapons(dt) {
                                      const nuke = weaponParts.nuke;

                                      if (
                                        !nuke ||
                                        !nuke.core ||
                                        !nuke.warning ||
                                        !nuke.smoke
                                      ) {
                                        return;
                                      }

                                      const t = performance.now() * 0.006;

                                      if (nuke.core.material) {
                                        nuke.core.scale.setScalar(
                                          1 + Math.sin(t) * 0.12
                                        );

                                        nuke.core.material.emissiveIntensity =
                                          3 + Math.sin(t) * 2;
                                      }

                                      if (nuke.warning.material) {
                                        nuke.warning.material.emissiveIntensity =
                                          Math.sin(t * 3) > 0 ? 6 : 1;
                                      }

                                      if (Math.random() < 0.04) {
                                        createNukeSmoke();
                                      }

                                      for (const smoke of nuke.smoke) {
                                        smoke.life -= dt;

                                        smoke.mesh.position.addScaledVector(
                                          smoke.velocity,
                                          dt
                                        );

                                        smoke.mesh.material.opacity =
                                          Math.max(0, smoke.life);

                                        smoke.mesh.scale.multiplyScalar(1.02);
                                      }

                                      nuke.smoke = nuke.smoke.filter(smoke => {
                                        if (smoke.life <= 0) {
                                          removeObject(smoke.mesh);
                                          return false;
                                        }

                                        return true;
                                      });
                                    }
