                strip.innerHTML = `<div class="ach-head">LIFETIME · ${life.kills.toLocaleString()} KILLS · ${life.runs} RUNS · BEST WAVE ${life.bestWave} · ACHIEVEMENTS ${count}/${total}</div>` +
                  Object.entries(ACHIEVEMENTS).map(([id, e]) =>
                    `<span class="${earned[id] ? 'on' : ''}" title="${e.name} — ${e.desc}">${e.icon}</span>`).join('');
