                const result = baseKill.apply(this, arguments);
                if (wasAlive && !e.alive && !run.done) {
                  run.kills++; life.kills++;
                  run.bestCombo = Math.max(run.bestCombo, comboCount);
                  life.bestCombo = Math.max(life.bestCombo, comboCount);
                  check();
                }
