              const surface=getSurfaceAtEnemy(e,probe.x,probe.z);
              const stand=new THREE.Vector3(probe.x,surface+bodyHeight(e),probe.z);
              const ok=enemyCanMoveTo(stand,r);
              const score=(ok?2.5:-1)+side.dot(desired)*2;
