        function finite(value, fallback = 0){
          return Number.isFinite(value) ? value : fallback;
        }

        function disposeOwned(object){
          if (!object || object.__ksDisposed120) return;
          object.__ksDisposed120 = true;
          try {
            if (typeof disposeObject === 'function') disposeObject(object);
          } catch (error) {
            console.warn('Killshift resource cleanup recovered:', error);
          }
        }

